import{_ as o,l as n,o as e,c as l,v as r,p as s,x as t,d as p,i as d,S as P}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"互联网拓扑与 IXP","description":"","frontmatter":{"title":"互联网拓扑与 IXP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/internet-ixp.md","filePath":"cs/internet-ixp.md","lastUpdated":1789023840000}'),h={name:"cs/internet-ixp.md"};function A(c,a,I,_,S,f){const i=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="互联网拓扑与-ixp" tabindex="-1">互联网拓扑与 IXP <a class="header-anchor" href="#互联网拓扑与-ixp" aria-label="Permalink to &quot;互联网拓扑与 IXP&quot;">​</a></h1><div class="epigraph"><p>AS 图不是随机图：客户–提供者层次加上 IXP 上的多边对等，让流量尽量在公共交换点「落地」而不绕供应商。</p><footer>—— 据 Gao and Rexford, IEEE/ACM ToN 2001 政策稳定；RFC 7948 IXP 相关讨论；CAIDA AS 关系研究通识整理</footer></div><p><a href="/cs/bgp-hijack-rpki">上一课</a> 护源。流量实际走哪张图？缺口是<strong>拓扑</strong>：层级、富俱乐部、IXP 交换机把许多 AS 接到同一二层。本课不把 MPLS TE 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若只有转供，小 AS 的流量爬到全球供应商再下来，贵且绕。IXP：共同交费连一台（或一组）交换机，双边/多边对等交换客户路由。这是「付费进房 + BGP」，不是免费全互联。拓扑测量：控制面看到的 AS_PATH 与数据面实际下一跳可能因热土豆不一致。RPKI 不画这张图，只验证源。</p><p>不要把 IXP 写成一个 AS：它通常不转供，只提供二层。</p><p><span class="marginnote">Gao–Rexford 条件保证某类政策下无永久振荡。route server 在 IXP 上减会话，像公共 RR。本课不点名具体交换点当广告。</span></p><h3 id="ixp-不转供" tabindex="-1">IXP 不转供 <a class="header-anchor" href="#ixp-不转供" aria-label="Permalink to &quot;IXP 不转供&quot;">​</a></h3><p>二层汇合加多方 BGP，不是一个 AS。对等无 SLA 也会拥塞。控制面路径与热土豆数据面可以分叉。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：层级供应商 + IXP 横边。对照校园以太网：IXP 也学 MAC，但上面跑很多 eBGP。LACP/MLAG 在 IXP 交换侧防单点，与校园同类。</p>',11)),(e(),s(P,null,{default:t(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20STUB%5B%22%E5%AD%98%E6%A0%B9%20AS%22%5D%20--%3E%20P%5B%22%E6%8F%90%E4%BE%9B%E8%80%85%22%5D%0A%20%20STUB%20--%3E%20IXP%5B%22IXP%20%E4%BA%8C%E5%B1%82%22%5D%0A%20%20P2%5B%22%E5%8F%A6%E4%B8%80%20AS%22%5D%20--%3E%20IXP%0A%20%20IXP%20--%3E%20BGP%5B%22%E5%A4%9A%E8%BE%B9%E5%AF%B9%E7%AD%89%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>流量工程后课会在这张图上挪入口。BGP 收敛事件在富连接图上扩散更快也更乱。卫星用户仍经关口 AS 进这张图。主干任播课：根 DNS 常出现在 IXP，是拓扑选择不是协议新字段。</p><p>route server：多边对等的控制面中心，数据面仍直连 IXP 交换机。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 peeringDB 的运维流程。流量工程是下一课。后课默认：互联网 = 政策图 + IXP 横连；不是 OSPF 一张度量图。</p><p>公开对等不等于承诺无拥塞：无 SLA 的对等口会满。</p><p>上一课留下的缺口在本课收口；「互联网拓扑与 IXP」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/traffic-engineering">流量工程</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>AS 关系决定默认路径；IXP 提供短的对等边。</li><li>IXP 是二层汇合，不是转供 AS。</li><li>控制面路径与数据面可能因热土豆分叉。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Gao–Rexford, 2001；IXP 运维通识。</li></ul>',10))])}const X=o(h,[["render",A]]);export{E as __pageData,X as default};
